//! The state of a mixture with the Wong-Sandler mixing rule against the
//! exact-source library.
//! Generated by tools/rust_port/validate_wong_sandler_state.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::excess_gibbs::MixingRule;
use thermopack_rs::wong_sandler::{Fraction, WongSandlerData};
use thermopack_rs::{Cubic, CubicKind, CubicOptions};

const ATOL: f64 = 1.0e-8;
const RTOL: f64 = 1.0e-9;

fn kind(name: &str) -> CubicKind {
    match name {
        "PR" => CubicKind::PengRobinson,
        "SRK" => CubicKind::SoaveRedlichKwong,
        "VDW" => CubicKind::VanDerWaals,
        other => panic!("unknown equation of state {other}"),
    }
}

#[test]
fn the_state_matches_the_source() {
    let mut rows = include_str!("fixtures/wong_sandler_state.csv").lines();
    let header = rows.next().expect("the header of the fixture");
    assert_eq!(
        header,
        "case;p;dpdv;dpdt;d2pdv2;h;s;lnphi_1;lnphi_2;dlnfugdt_1;dlnfugdt_2;dlnfugdp_1;dlnfugdp_2;dlnfugdn_1_1;dlnfugdn_1_2;dlnfugdn_2_1;dlnfugdn_2_2"
    );
    let mut compared = 0;
    for row in rows {
        let fields: Vec<&str> = row.split(';').collect();
        assert_eq!(fields.len(), 17, "row {row}");
        let case: Vec<&str> = fields[0].split('|').collect();
        assert_eq!(case.len(), 9, "case {row}");
        let components: Vec<&str> = case[2].split(',').collect();
        let temperature: f64 = case[3].parse().expect("the temperature");
        let volume: f64 = case[4].parse().expect("the molar volume");
        let composition: Vec<f64> = case[5]
            .split(',')
            .map(|value| value.parse().expect("the number of moles"))
            .collect();
        let kij: f64 = case[6].parse().expect("the binary interaction parameter");
        let tauij: f64 = case[7]
            .parse()
            .expect("the parameter of the second order term");
        let alpha: f64 = case[8]
            .parse()
            .expect("the exponent of the second order term");

        let mut data = WongSandlerData::new(components.len());
        data.set_kij(0, 1, Fraction::constant(kij))
            .expect("the parameter");
        data.set_kij(1, 0, Fraction::constant(kij))
            .expect("the parameter");
        data.set_tauij(0, 1, Fraction::constant(tauij))
            .expect("the parameter");
        data.set_tauij(1, 0, Fraction::constant(tauij))
            .expect("the parameter");
        data.set_alphaij(0, 1, alpha).expect("the exponent");
        data.set_alphaij(1, 0, alpha).expect("the exponent");
        let options = CubicOptions {
            mixing_rule: MixingRule::WongSandler,
            wong_sandler: Some(&data),
            ..Default::default()
        };
        let model = Cubic::with_options(kind(case[1]), &components, options).expect("the model");
        let state = model
            .prepare(temperature, &composition)
            .expect("the prepared state");
        let pressure = state.pressure(volume).expect("the pressure");
        let mut fugacity = vec![0.0; components.len()];
        state
            .ln_fugacity_into(volume, &mut fugacity)
            .expect("the fugacity");
        let mut dt = vec![0.0; components.len()];
        let mut dp = vec![0.0; components.len()];
        let mut dn = vec![0.0; components.len() * components.len()];
        state
            .fugacity_derivatives_into(volume, &mut dt, &mut dp, &mut dn)
            .expect("the fugacity derivatives");
        let mut native = vec![
            pressure.value,
            pressure.dv,
            pressure.dt,
            state
                .pressure_second_derivative(volume)
                .expect("the second pressure derivative"),
            state.enthalpy(volume).expect("the enthalpy"),
            state.entropy(volume).expect("the entropy"),
        ];
        native.extend(fugacity);
        native.extend(dt);
        native.extend(dp);
        native.extend(dn);

        for (position, (source, native)) in fields[1..].iter().zip(native.iter()).enumerate() {
            let source: f64 = source.parse().expect("the source value");
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "entry {position} of the case {row}: source {source} native {native}"
            );
        }
        compared += 1;
    }
    assert!(compared > 0, "the fixture holds no case");
}
